package financeos.cloud;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.io.*;import java.util.function.Supplier;import javax.xml.parsers.*;import org.w3c.dom.*;import com.fasterxml.jackson.databind.*;
/** Deletes only recognized recovery/processed-technical objects; never the current state or base. */
public final class StorageRetention {
 public record Item(String key,String version,boolean latest,long size,Instant modified){}
 public record Result(long bytes,int removed,boolean incomplete){}
 private final HttpClient http;private final URI root;private final Supplier<String> token;private final String stateKey;
 public StorageRetention(HttpClient http,URI endpoint,String bucket,Supplier<String> token,String stateKey){this.http=http;this.root=endpoint.resolve("/"+bucket+"/");this.token=token;this.stateKey=stateKey;}
 static String value(Element e,String name){for(var n=e.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element c&&name.equals(c.getLocalName()==null?c.getTagName():c.getLocalName()))return c.getTextContent();return "";}
 static Document xml(byte[] bytes)throws Exception{var f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);return f.newDocumentBuilder().parse(new ByteArrayInputStream(bytes));}
 private byte[] request(String query,String method)throws Exception{var req=HttpRequest.newBuilder(URI.create(root.toString()+query)).timeout(Duration.ofSeconds(10)).header("Authorization","Bearer "+token.get()).method(method,HttpRequest.BodyPublishers.noBody()).build();var r=http.send(req,HttpResponse.BodyHandlers.ofByteArray());if(r.statusCode()!=200&&r.statusCode()!=204)throw new IOException("Storage retention HTTP "+r.statusCode());return r.body();}
 private static String q(String s){return URLEncoder.encode(s,StandardCharsets.UTF_8).replace("+","%20");}
 public List<Item> inventory(String prefix)throws Exception{var out=new ArrayList<Item>();String key="",version="";for(int page=0;page<50;page++){String query="?versions=&max-keys=1000&prefix="+q(prefix)+(key.isEmpty()?"":"&key-marker="+q(key)+"&version-id-marker="+q(version));var doc=xml(request(query,"GET")).getDocumentElement();for(var n=doc.getFirstChild();n!=null;n=n.getNextSibling())if(n instanceof Element e&&"Version".equals(e.getLocalName()==null?e.getTagName():e.getLocalName()))out.add(new Item(value(e,"Key"),value(e,"VersionId"),value(e,"IsLatest").equals("true"),Long.parseLong(value(e,"Size")),Instant.parse(value(e,"LastModified"))));if(!value(doc,"IsTruncated").equals("true"))return List.copyOf(out);String next=value(doc,"NextKeyMarker");if(next.isBlank()||next.equals(key)&&value(doc,"NextVersionIdMarker").equals(version))throw new IOException("Invalid retention pagination");key=next;version=value(doc,"NextVersionIdMarker");}throw new IOException("Retention inventory too large");}
 public static List<Item> eventDeletes(List<Item> items){var events=items.stream().filter(i->i.latest()&&i.key().matches("java-v1/restore-points/events/[0-9T]+-[a-f0-9]{64}\\.json")).sorted(Comparator.comparing(Item::key).reversed()).toList();return events.stream().skip(20).toList();}
 private void delete(Item i)throws Exception{boolean recovery=i.key().matches("java-v1/restore-points/(events/[0-9T]+-[a-f0-9]{64}|daily/[0-9-]{10})\\.json");boolean technical=i.key().matches("inbox/[a-f0-9]{64}\\.json");if(!recovery&&!technical||i.version().isBlank())throw new IOException("Unsafe retention target");var req=HttpRequest.newBuilder(URI.create(root.toString()+i.key()+"?versionId="+q(i.version()))).timeout(Duration.ofSeconds(10)).header("Authorization","Bearer "+token.get()).DELETE().build();var r=http.send(req,HttpResponse.BodyHandlers.discarding());if(r.statusCode()!=200&&r.statusCode()!=204)throw new IOException("Retention delete rejected");}
 public void trimEvents()throws Exception{for(var item:eventDeletes(inventory("java-v1/restore-points/events/")))delete(item);}
 public static boolean processed(JsonNode event,CloudVkProcessor.Envelope env,long group,long peer){String id=CloudVkIngress.eventId(new financeos.vk.VkEvent(event.path("type").asText(),event.path("groupId").asLong(),event.path("userId").asLong(),event.path("peerId").asLong(),event.path("eventId").asText(),""));var reply=env.replies().get(id);if(reply!=null&&!reply.delivered())return false;return event.path("groupId").asLong()==group&&event.path("peerId").asLong()==peer&&event.path("conversationMessageId").asLong()>0&&event.path("conversationMessageId").asLong()<=env.lastConversationMessageId();}
 public Result maintain(CloudVkProcessor.Envelope env,long group,long peer,Instant now)throws Exception{var items=inventory("");var candidates=new ArrayList<>(eventDeletes(items));LocalDate threshold=now.atZone(ZoneId.of("Europe/Moscow")).toLocalDate().minusDays(29);for(var i:items){if(i.latest()&&i.key().matches("java-v1/restore-points/daily/[0-9-]{10}\\.json")&&LocalDate.parse(i.key().substring(i.key().lastIndexOf('/')+1,i.key().length()-5)).isBefore(threshold))candidates.add(i);}
 long used=items.stream().mapToLong(Item::size).sum();int removed=0;long end=System.nanoTime()+Duration.ofSeconds(30).toNanos();for(var i:candidates){if(System.nanoTime()>end)return new Result(used,removed,true);delete(i);used-=i.size();removed++;}
 var mapper=new ObjectMapper();for(var i:items)if(i.latest()&&i.key().matches("inbox/[a-f0-9]{64}\\.json")&&i.modified().isBefore(now.minus(Duration.ofDays(7)))){if(System.nanoTime()>end)return new Result(used,removed,true);var req=HttpRequest.newBuilder(root.resolve(i.key())).timeout(Duration.ofSeconds(5)).header("Authorization","Bearer "+token.get()).GET().build();var r=http.send(req,HttpResponse.BodyHandlers.ofByteArray());if(r.statusCode()==200&&processed(mapper.readTree(r.body()),env,group,peer)){delete(i);used-=i.size();removed++;}}
 return new Result(used,removed,false);}
}
